function stage2ListingDescriptionHint(category, subcategory, type) {
  if (category === 'Услуги') {
    if (type === 'Търси') return `Опиши каква ${subcategory || 'услуга'} търсиш, къде е задачата и кога ти е необходим изпълнител.`;
    return `Опиши какви ${subcategory || 'услуги'} предлагаш, район, срок и важни условия.`;
  }
  if (category === 'Работа') {
    return type === 'Търси работа'
      ? 'Опиши опита, квалификацията, каква работа търсиш и кога можеш да започнеш.'
      : 'Опиши длъжността, графика, изискванията, условията и начина за кандидатстване.';
  }
  if (category === 'Имоти') return 'Опиши вида на имота, района, състоянието, площта и най-важните условия по сделката.';
  if (category === 'Автомобили и МПС') return 'Опиши МПС или частта: марка/модел, година или съвместимост, състояние и важни подробности.';
  if (category === 'Животни') return 'Опиши ясно ситуацията, вида на животното или стоката, района и как човек може да помогне или да се свърже.';
  return 'Опиши най-важното ясно и конкретно.';
}

